SELECT w.class_Id, s.value, (SELECT value FROM weenie_properties_int WHERE object_Id = w.class_Id AND type = 25) AS level, (SELECT current_Level FROM weenie_properties_attribute_2nd WHERE object_Id = w.class_Id AND type = 1) AS health FROM weenie w JOIN weenie_properties_string s ON s.object_Id = w.class_Id AND s.type = 1 WHERE w.class_Id BETWEEN 902300 AND 902329;
SELECT HEX(guid), weenie_Class_Id, HEX(obj_Cell_Id), origin_X, origin_Y, origin_Z FROM landblock_instance WHERE weenie_Class_Id BETWEEN 902300 AND 902329;
